{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be a dict")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    for node in nodes:
        if node not in core_distance:
            raise ValueError("Missing core distance for node: " + str(node))

    # Compute mutual reachability for each edge
    mr_edges = []
    for edge in distances:
        if len(edge) != 3:
            raise ValueError("Each edge must have exactly 3 elements")
        u, v, dist = edge[0], edge[1], edge[2]
        if u not in core_distance:
            raise ValueError("Missing core distance for node: " + str(u))
        if v not in core_distance:
            raise ValueError("Missing core distance for node: " + str(v))
        mr = max(core_distance[u], core_distance[v], dist)
        # Canonicalize undirected endpoints lexicographically
        a, b = (u, v) if u <= v else (v, u)
        mr_edges.append((mr, a, b))

    # Sort by mutual reachability, then by first endpoint, then second
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Kruskal's MST with union-find (rank-based union + path compression)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while x != root:
            next_x = parent[x]
            parent[x] = root
            x = next_x
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
